"""Generate .importlinter from the components.json files at both levels (ADR-0020).

Never edit .importlinter by hand. ``--check`` fails when the committed file is stale.

Usage: uv run python tools/quality/python/gen_importlinter.py [--check]
"""

from __future__ import annotations

import sys
from pathlib import Path

import archgraph

TARGET = archgraph.ROOT / ".importlinter"
HEADER = (
    "# Generated by tools/quality/python/gen_importlinter.py from components.json. Do not edit.\n"
)


def _contract(cid: str, name: str, lines: list[str]) -> str:
    return f"\n[importlinter:contract:{cid}]\nname = {name}\n" + "\n".join(lines) + "\n"


def _listing(key: str, modules: list[str]) -> list[str]:
    return [f"{key} ="] + [f"    {m}" for m in sorted(modules)]


def _forbidden(cid: str, name: str, sources: list[str], forbidden: list[str]) -> str:
    lines = ["type = forbidden", *_listing("source_modules", sources)]
    lines += [*_listing("forbidden_modules", forbidden), "allow_indirect_imports = True"]
    return _contract(cid, name, lines)


def _banned(unit: archgraph.Unit, units: list[archgraph.Unit], is_system: bool) -> list[str]:
    """Packages of every unit this unit must not import."""
    out: list[str] = []
    for other in units:
        if other.name == unit.name:
            continue
        if (is_system and other.kind == "app") or other.name not in unit.may_depend_on:
            out.extend(other.packages)
    return out


def _acyclic(level: str, units: list[archgraph.Unit], existing: set[str]) -> list[str]:
    apps = sorted({p.split(".")[0] for u in units for p in u.packages} & existing)
    lines = ["type = acyclic_siblings", "depth = 1"]
    return [
        _contract(f"{level}-acyclic", f"{level}: no cycles", [*lines, f"ancestors = {pkg}"])
        for pkg in apps
    ]


def _level_contracts(path: Path, existing: set[str]) -> list[str]:
    is_system, units = archgraph.load_units(path)
    level = "system" if is_system else path.parts[-4]
    out: list[str] = []
    for unit in units:
        sources = [p for p in unit.packages if p in existing]
        banned = [p for p in _banned(unit, units, is_system) if p in existing]
        if sources and banned:
            title = f"{level}: {unit.name} imports only its mayDependOn"
            out.append(_forbidden(f"{level}-{unit.name}", title, sources, banned))
    return out if is_system else out + _acyclic(level, units, existing)


def render() -> str:
    graph = archgraph.build_graph()
    existing = {m for m in graph.modules if not graph.is_module_squashed(m)}
    roots = archgraph.top_packages()
    text = HEADER + "\n[importlinter]\n" + "\n".join(_listing("root_packages", roots)) + "\n"
    text += "include_external_packages = True\n"
    for path in [archgraph.ROOT_COMPONENTS, *archgraph.app_components_files()]:
        text += "".join(_level_contracts(path, existing))
    return text


def main() -> int:
    text = render()
    if "--check" in sys.argv[1:]:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != text:
            print(
                ".importlinter is stale: run tools/quality/python/gen_importlinter.py",
                file=sys.stderr,
            )
            return 1
        return 0
    TARGET.write_text(text, encoding="utf-8")
    print(f"wrote {Path(TARGET).relative_to(archgraph.ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
